import test from 'node:test';
import assert from 'node:assert/strict';
import { csvToMarkdownTable, parseCsv } from './convert.mjs';

test('parseCsv splits plain rows on commas', () => {
  const rows = parseCsv('name,age\nAda,36\nGrace,85\n');
  assert.deepEqual(rows, [
    ['name', 'age'],
    ['Ada', '36'],
    ['Grace', '85'],
  ]);
});

test('parseCsv keeps a comma inside quotes as one field', () => {
  const rows = parseCsv('name,notes\nAda,"Ships in 2, sometimes 3 days"\n');
  assert.deepEqual(rows, [
    ['name', 'notes'],
    ['Ada', 'Ships in 2, sometimes 3 days'],
  ]);
});

test('parseCsv unescapes doubled quotes inside a quoted field', () => {
  const rows = parseCsv('name,notes\nAda,"Has a ""quiet"" switch"\n');
  assert.deepEqual(rows, [
    ['name', 'notes'],
    ['Ada', 'Has a "quiet" switch'],
  ]);
});

test('csvToMarkdownTable renders a header, separator, and body rows', () => {
  const table = csvToMarkdownTable('name,age\nAda,36\nGrace,85\n');
  assert.equal(
    table,
    ['| name | age |', '| --- | --- |', '| Ada | 36 |', '| Grace | 85 |'].join('\n'),
  );
});

test('csvToMarkdownTable escapes a pipe character in a cell', () => {
  const table = csvToMarkdownTable('name,notes\nAda,"switch | tactile"\n');
  assert.equal(table, ['| name | notes |', '| --- | --- |', '| Ada | switch \\| tactile |'].join('\n'));
});

test('csvToMarkdownTable returns an empty string for empty input', () => {
  assert.equal(csvToMarkdownTable(''), '');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv, toMarkdownTable, csvToMarkdownTable } from './convert.mjs';

test('parseCsv splits simple rows into fields', () => {
  const rows = parseCsv('a,b,c\n1,2,3\n');
  assert.deepEqual(rows, [
    ['a', 'b', 'c'],
    ['1', '2', '3'],
  ]);
});

test('parseCsv handles quoted fields with embedded commas and quotes', () => {
  const rows = parseCsv('name,note\n"Doe, Jane","She said ""hi"""\n');
  assert.deepEqual(rows, [
    ['name', 'note'],
    ['Doe, Jane', 'She said "hi"'],
  ]);
});

test('toMarkdownTable renders a header, separator, and body rows', () => {
  const table = toMarkdownTable([
    ['name', 'role'],
    ['Ada', 'Mathematician'],
  ]);
  assert.equal(table, '| name | role |\n| --- | --- |\n| Ada | Mathematician |');
});

test('toMarkdownTable escapes pipe and backslash characters in cell values', () => {
  const table = toMarkdownTable([['expr'], ['a|b\\c']]);
  assert.equal(table, '| expr |\n| --- |\n| a\\|b\\\\c |');
});

test('csvToMarkdownTable converts CSV text straight to a markdown table', () => {
  const table = csvToMarkdownTable('name,years\nAda,3\nGrace,7\n');
  assert.equal(
    table,
    '| name | years |\n| --- | --- |\n| Ada | 3 |\n| Grace | 7 |',
  );
});

import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";

import { csvToMarkdownTable, parseCsv } from "./convert.mjs";

test("parseCsv splits simple rows on commas and newlines", () => {
  const rows = parseCsv("name,role\nAda,Mathematician\nGrace,Programmer\n");
  assert.deepEqual(rows, [
    ["name", "role"],
    ["Ada", "Mathematician"],
    ["Grace", "Programmer"],
  ]);
});

test("parseCsv handles quoted fields containing commas", () => {
  const rows = parseCsv('name,bio\nAda,"Mathematician, writer"\n');
  assert.deepEqual(rows, [
    ["name", "bio"],
    ["Ada", "Mathematician, writer"],
  ]);
});

test("parseCsv handles escaped quotes inside quoted fields", () => {
  const rows = parseCsv('quote\n"She said ""hi"""\n');
  assert.deepEqual(rows, [["quote"], ['She said "hi"']]);
});

test("parseCsv ignores a trailing blank line", () => {
  const rows = parseCsv("a,b\n1,2\n");
  assert.deepEqual(rows, [
    ["a", "b"],
    ["1", "2"],
  ]);
});

test("csvToMarkdownTable renders a header, separator, and body rows", () => {
  const table = csvToMarkdownTable(
    "name,role,years\nAda Lovelace,Mathematician,3\nGrace Hopper,Programmer,10\n",
  );
  assert.equal(
    table,
    [
      "| name | role | years |",
      "| --- | --- | --- |",
      "| Ada Lovelace | Mathematician | 3 |",
      "| Grace Hopper | Programmer | 10 |",
      "",
    ].join("\n"),
  );
});

test("csvToMarkdownTable escapes pipe and backslash characters", () => {
  const table = csvToMarkdownTable("a,b\n1|2,C:\\path\n");
  assert.equal(table, ["| a | b |", "| --- | --- |", "| 1\\|2 | C:\\\\path |", ""].join("\n"));
});

test("csvToMarkdownTable converts embedded newlines to <br>", () => {
  const table = csvToMarkdownTable('note\n"line one\nline two"\n');
  assert.equal(table, ["| note |", "| --- |", "| line one<br>line two |", ""].join("\n"));
});

test("csvToMarkdownTable pads rows with fewer fields than the header", () => {
  const table = csvToMarkdownTable("a,b,c\n1,2\n");
  assert.equal(table, ["| a | b | c |", "| --- | --- | --- |", "| 1 | 2 |  |", ""].join("\n"));
});

test("csvToMarkdownTable returns an empty string for empty input", () => {
  assert.equal(csvToMarkdownTable(""), "");
});

test("CLI reads a file path argument and prints the table", () => {
  const dir = mkdtempSync(join(tmpdir(), "csv-to-table-"));
  const csvPath = join(dir, "data.csv");
  writeFileSync(csvPath, "name,role\nAda,Mathematician\n");

  const output = execFileSync("node", [new URL("./convert.mjs", import.meta.url).pathname, csvPath], {
    encoding: "utf8",
  });

  assert.equal(output, ["| name | role |", "| --- | --- |", "| Ada | Mathematician |", ""].join("\n"));
});

test("CLI reads CSV from stdin when no file path is given", () => {
  const output = execFileSync("node", [new URL("./convert.mjs", import.meta.url).pathname], {
    encoding: "utf8",
    input: "name,role\nAda,Mathematician\n",
  });

  assert.equal(output, ["| name | role |", "| --- | --- |", "| Ada | Mathematician |", ""].join("\n"));
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { csvToMarkdownTable } from './convert.mjs';

test('converts a simple csv', () => {
  const csv = 'name,age\nAlice,30\nBob,25\n';
  const expected = '| name | age |\n| --- | --- |\n| Alice | 30 |\n| Bob | 25 |\n';
  assert.equal(csvToMarkdownTable(csv), expected);
});

test('handles quoted fields containing commas', () => {
  const csv = 'name,city\n"Doe, Jane","New York"\n';
  const expected = '| name | city |\n| --- | --- |\n| Doe, Jane | New York |\n';
  assert.equal(csvToMarkdownTable(csv), expected);
});

test('escapes pipe characters in cell values', () => {
  const csv = 'expr,result\n"a|b",true\n';
  const expected = '| expr | result |\n| --- | --- |\n| a\\|b | true |\n';
  assert.equal(csvToMarkdownTable(csv), expected);
});

test('unescapes doubled quotes as a literal quote', () => {
  const csv = 'quote\n"She said ""hi"""\n';
  const expected = '| quote |\n| --- |\n| She said "hi" |\n';
  assert.equal(csvToMarkdownTable(csv), expected);
});

test('collapses newlines inside quoted fields to <br>', () => {
  const csv = 'note\n"line one\nline two"\n';
  const expected = '| note |\n| --- |\n| line one<br>line two |\n';
  assert.equal(csvToMarkdownTable(csv), expected);
});

test('pads rows that are missing trailing cells', () => {
  const csv = 'a,b,c\n1,2\n';
  const expected = '| a | b | c |\n| --- | --- | --- |\n| 1 | 2 |  |\n';
  assert.equal(csvToMarkdownTable(csv), expected);
});

test('returns an empty string for empty input', () => {
  assert.equal(csvToMarkdownTable(''), '');
});
